const telegramId = $('Parse Input').item.json.telegramId;

let query;
if (telegramId) {
  query = `
SELECT
  d.id AS draft_id,
  d.topic_id,
  d.script_hook,
  d.script_body,
  d.script_cta,
  d.full_script,
  d.status,
  d.revision_count,
  d.word_count
FROM public.youtube_drafts d
JOIN public.youtube_topics t ON t.id = d.topic_id
JOIN public.telegram_users u ON u.id = t.telegram_user_id
WHERE u.telegram_id = ${telegramId}
ORDER BY d.created_at DESC
LIMIT 1;
`;
} else {
  // Chat UI fallback — ultimul draft din DB
  query = `
SELECT
  d.id AS draft_id,
  d.topic_id,
  d.script_hook,
  d.script_body,
  d.script_cta,
  d.full_script,
  d.status,
  d.revision_count,
  d.word_count
FROM public.youtube_drafts d
ORDER BY d.created_at DESC
LIMIT 1;
`;
}

return [{ json: {
  query: query.trim(),
  chatId: $('Parse Input').item.json.chatId
} }];

const parseInput = $('Parse Input').item.json;
const upsertUser = $('Upsert Telegram User').item.json;

const telegramUserId = upsertUser.id;
const inputType = parseInput.inputType || 'keyword';
const text = parseInput.text || '';
const inputUrl = parseInput.inputUrl || null;
const keyword = inputType !== 'url' ? text : null;

const keywordSql = keyword ? `'${keyword.replace(/'/g, "''")}'` : 'NULL';
const inputUrlSql = inputUrl ? `'${inputUrl.replace(/'/g, "''")}'` : 'NULL';

const query = `INSERT INTO youtube_topics (telegram_user_id, keyword, input_url, input_type) VALUES ('${telegramUserId}', ${keywordSql}, ${inputUrlSql}, '${inputType}') RETURNING id;`;

return [{ json: { query, telegram_user_id: telegramUserId, keyword, input_url: inputUrl, input_type: inputType } }];

// Universal Input Parser
const isTelegram = !!$json.message;
const msg = $json.message || {};

const text = isTelegram
  ? (msg.text || '').trim()
  : ($json.chatInput || $json.input || $json.text || '').trim();

if (!text) {
  return [{ json: { error: 'No input text found', raw: $json, _source: isTelegram ? 'telegram' : 'chat-ui' }}];
}

const telegramId = isTelegram ? (msg.from?.id || null) : null;
const username = isTelegram ? (msg.from?.username || '') : 'chat-user';
const firstName = isTelegram ? (msg.from?.first_name || '') : 'User';
const chatId = isTelegram ? (msg.chat?.id || null) : ($json.sessionId || 'chat-ui');
const messageId = isTelegram ? (msg.message_id || null) : null;

const urlRegex = /https?:\/\/[^\s]+/i;
const isUrl = urlRegex.test(text);
const inputUrl = isUrl ? text.match(urlRegex)[0] : null;
const inputType = isUrl ? 'url' : 'keyword';

const revisionKeywords = /^(revise|redo|regenerate|modifica|refa|schimba|rescrie|rewrite)/i;
const isRevision = revisionKeywords.test(text);

return [{ json: { chatId, telegramId, username, firstName, text, inputType, inputUrl, isRevision, messageId, _source: isTelegram ? 'telegram' : 'chat-ui' }}];

const parseInput = $input.first().json;
const inputType = parseInput.inputType || 'keyword';
const text = parseInput.text || '';
const inputUrl = parseInput.inputUrl || null;
const keyword = inputType !== 'url' ? text : null;

return [{ 
  json: { 
    telegram_user_id: parseInput.telegramId || null, 
    keyword: keyword, 
    input_url: inputUrl, 
    input_type: inputType, 
    raw_text: text, 
    chatId: parseInput.chatId 
  }
}];

const topic = $('Create a row').first().json;
if (!topic || !topic.id) { 
  return [{ json: { error: 'No topic created', stage: 'insert_topic' }}]; 
}
return [{ 
  json: { 
    cleanedContent: $('Parse Input2').first().json.text, 
    source: 'keyword', 
    topicId: topic.id, 
    chatId: $('Parse Input2').first().json.chatId 
  }
}];

