// Incercam sa cream un fisier de playlist M3U8 care poate fi redat
// direct din Google Drive fara procesare server-side
const m3u8Lines = ['#EXTM3U', '#EXT-X-VERSION:3', '#EXT-X-TARGETDURATION:5'];
for (const clip of data.clips) {
  m3u8Lines.push('#EXTINF:5.0,');
  m3u8Lines.push('https://drive.google.com/uc?id=' + clip.driveFileId);
}
m3u8Lines.push('#EXT-X-ENDLIST');

const playlistContent = m3u8Lines.join('\n');

return [{ json: {
  ...data,
  playlistContent,
  method: 'drive_playlist',
  message: '📹 Clipurile (' + data.clipCount + ') sunt uploadate în Drive. Playlist M3U8 generat pentru preview. Concatenare finală cu audio necesită procesare manuală sau FFmpeg.',
  ready: true
} }];

// Salveaza playlist M3U8 in Drive si notifica utilizatorul
const data = $input.first().json;

const playlistBuffer = Buffer.from(data.playlistContent || '', 'utf-8');
const binaryData = await this.helpers.prepareBinaryData(
  playlistBuffer,
  data.slug + '-playlist.m3u8',
  'application/x-mpegURL'
);

return [{
  json: {
    folderId: data.folderId,
    filename: data.slug + '-playlist.m3u8',
    slug: data.slug,
    chatId: data.chatId,
    message: data.message,
    clipCount: data.clipCount
  },
  binary: { data: binaryData }
}];

